# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List

from rosterkit.models import Student


def _label(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _sort_key(student: Student) -> tuple:
    return (student.last_name, student.first_name)


def _check(students: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")


def _chunks(names: List[str], seats: int) -> List[str]:
    return [
        " | ".join(names[start : start + seats])
        for start in range(0, len(names), seats)
    ]


def seating_rows(students: List[Student], seats: int):
    """One text line per row, sorted by last name."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    names = [_label(item) for item in ordered]
    rows = _chunks(names, seats)
    pairs = enumerate(rows, 1)
    return [f"Row {index}: {row}" for index, row in pairs]

after.tests/test_seating.py:
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def _pupil(last, first):
    return Student("id", last, first, "A")


def _pupils():
    return [
        _pupil("Halloway", "Juno"),
        _pupil("Zed", "Amy"),
        _pupil("Dunmere", "Piet"),
    ]


class SeatingTests(unittest.TestCase):
    def test_sorted_rows(self):
        rows = seating_rows(_pupils(), 2)
        self.assertEqual(rows, [
            "Row 1: Dunmere, Piet | Halloway, Juno",
            "Row 2: Zed, Amy",
        ])

    def test_bad_seat_counts(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(_pupils(), seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
